#!/usr/bin/env python3
"""Build the public Omnequa site; canonical journal content comes from GitHub."""
from pathlib import Path
from html import escape
from datetime import datetime
from email.utils import parsedate_to_datetime
import json, re, shutil, runpy, xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
BASE='https://omnequa.org'
BLOG='https://github.com/scottonchain/microcredit-vision'
RAW='https://raw.githubusercontent.com/scottonchain/microcredit-vision/main'
# Preserve existing dated reports and the old evidence pages without presenting
# their expired invitations or operating goals as current offers.
runpy.run_path(str(ROOT/'tools/build_legacy.py'))
for slug in ['mission','opportunities','partners','evidence','newsroom','contact']:
    target=OUT/'archive'/slug
    target.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(OUT/slug/'index.html',target/'index.html')
for path in (OUT/'archive').glob('*/index.html'):
    s=path.read_text().replace('<body>','<body class="archive-page">').replace('<main id="main">','<main id="main"><div class="archive-banner">Historical snapshot · October 2026. Dates, invitations and targets below are historical. <a href="/history/">Read the current history →</a></div>')
    s=s.replace('href="/feed.xml"', 'href="'+RAW+'/feed.xml"')
    for old_route in ['mission','opportunities','partners','evidence','newsroom','contact']:
        s=s.replace('href="/'+old_route+'/', 'href="/archive/'+old_route+'/')
    path.write_text(s)
for path in (OUT/'journal').glob('*/index.html'):
    s=path.read_text().replace('<body>','<body class="archive-page">').replace('<main id="main">','<main id="main"><div class="archive-banner">From the October 2026 website archive. <a href="/journal/">Read the current journal →</a></div>')
    s=s.replace('<p class="note">This report describes website work and goals. It makes no claim of a verified human payout.</p>','')
    s=s.replace('href="/feed.xml"', 'href="'+RAW+'/feed.xml"')
    for old_route in ['mission','opportunities','partners','evidence','newsroom','contact']:
        s=s.replace('href="/'+old_route+'/', 'href="/archive/'+old_route+'/')
    path.write_text(s)
for name in ['style.css','journal.js']:
    shutil.copyfile(ROOT/'assets'/name,OUT/name)
NS={'a':'http://www.w3.org/2005/Atom'}
atom=ET.parse(ROOT/'content/blog-atom.xml').getroot()
posts=[]
for e in atom.findall('a:entry',NS):
    url=e.find('a:link',NS).get('href')
    slug=url.rsplit('/',1)[-1].removesuffix('.md')
    posts.append(dict(id=url,slug=slug,title=e.findtext('a:title','',NS),date=e.findtext('a:published','',NS),author=e.findtext('a:author/a:name','',NS),summary=e.findtext('a:summary','',NS),tags=[x.get('term') for x in e.findall('a:category',NS)],url=url))
feed={'version':1,'updated':atom.findtext('a:updated','',NS),'posts':posts}
# A reviewed full-content export supersedes the Atom metadata snapshot.
if (ROOT/'content/blog-feed.json').exists():
    feed=json.loads((ROOT/'content/blog-feed.json').read_text())
    posts=feed['posts']
# Reviewed chart copies provide a fallback if public GitHub image delivery fails.
# The browser always tries the canonical image first, preserving future corrections.
mirrors={}
for chart in (ROOT/'assets/journal').rglob('*.svg'):
    rel=chart.relative_to(ROOT/'assets/journal')
    dest=OUT/'journal-assets'/rel
    dest.parent.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(chart,dest)
    mirrors[RAW+'/images/'+rel.as_posix()]='/journal-assets/'+rel.as_posix()
feed['image_mirrors']=mirrors
feed.update(json.loads((ROOT/'content/publication.json').read_text()) if (ROOT/'content/publication.json').exists() else {})
(OUT/'journal-feed.json').write_text(json.dumps(feed,ensure_ascii=False))
shutil.copyfile(ROOT/'content/blog-atom.xml', OUT/'feed.xml')
from theme import document
shutil.copytree(ROOT/'assets/brand',OUT/'brand',dirs_exist_ok=True)
routes=[]
def page(slug,title,desc,body,script=False,archive=False):
    routes.append(slug)
    folder=OUT if slug=='home' else OUT/slug
    folder.mkdir(parents=True,exist_ok=True)
    (folder/'index.html').write_text(document(slug,title,desc,body,script,archive))
def top(kicker,title,desc):
    return '<section class="page-top wrap"><p class="eyebrow">'+kicker+'</p><h1>'+title+'</h1><p class="lede">'+desc+'</p></section>'
def card(p):
    target='/journal/read/?slug='+p['slug'] if p.get('content_html') else p['url']
    return f'<article class="post-card"><p class="eyebrow">{escape(p["date"][:10])} · {escape((p.get("tags") or ["Journal"])[0].replace("-"," "))}</p><h3><a href="{escape(target)}">{escape(p["title"])}</a></h3><p>{escape(p["summary"])}</p><span class="read-more" aria-hidden="true">Read the story →</span></article>'
def listing(limit):
    return '<div class="journal-grid" data-journal-list data-limit="'+str(limit)+'">'+''.join(card(p) for p in posts[:limit])+'</div><p class="feed-note" data-feed-status>Research and stories from the Omnequa team. <a href="'+BLOG+'">Also on GitHub ↗</a></p>'
home='''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">Technology with a human purpose</p><h1>New technology.<br><em>More opportunity.</em></h1><p class="lede">We explore how AI and open financial tools can help people earn a better living. Our purpose is simple: alleviate human poverty.</p><div class="actions"><a class="button" href="/journal/">Explore the journal <span aria-hidden="true">→</span></a><a class="text-link" href="/about/">Meet Omnequa</a></div><p class="hero-footnote">Independent research. AI-led work. Human direction.</p></div><figure class="hero-art"><img src="/brand/omnequa-logo.png" alt="The Omnequa logo: two hands supporting a faceted teal symbol" width="830" height="830" fetchpriority="high"><figcaption>Human opportunity is the point.</figcaption></figure></section>
<section class="purpose-strip"><div class="wrap"><p class="eyebrow">Our guiding question</p><p>When technology creates value,<br><strong>how does that value reach people?</strong></p><a class="text-link" href="/how-we-work/">Explore our approach →</a></div></section>
<section class="journal-section wrap"><div class="section-heading"><div><p class="eyebrow">The Omnequa journal · Credit Among Strangers</p><h2>A changing economy.<br>Explained for people.</h2></div><a class="text-link" href="/journal/">All stories →</a></div>'''+listing(4)+'''</section>
<section class="mission-band"><div class="wrap split"><div><p class="eyebrow">What we are exploring</p><h2>Useful work.<br>Income people<br>can use.</h2></div><div><p>AI agents are software that can carry out tasks. Behind most agents is a person or business paying the bills. That puts a human question at the center of the story: who gets to own the business and share in its income?</p><p>We are exploring digital work, creator businesses and virtual economies, looking for practical ways to lower the cost of getting started and help useful businesses grow.</p><a class="text-link" href="/how-we-work/">See our current direction →</a></div></div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">Start here</p><h2>Get to know Omnequa.</h2></div></div><div class="explainer-grid"><a href="/about/"><span>01 / The people and the purpose</span><h3>A human mission.<br>An AI team.</h3><p>Who does the work, what guides it, and why it matters.</p><b aria-hidden="true">↗</b></a><a href="/history/"><span>02 / Our story</span><h3>Same purpose.<br>New possibilities.</h3><p>How our work evolved from access to credit to digital opportunity.</p><b aria-hidden="true">↗</b></a><a href="/newsroom/"><span>03 / Press and creators</span><h3>A story worth<br>understanding.</h3><p>A quick introduction, background, story angles and the Omnequa logo.</p><b aria-hidden="true">↗</b></a></div></section>
<section class="contact-band wrap"><div><p class="eyebrow">Join the conversation</p><h2>Good questions<br>move us forward.</h2></div><div><p>Writing a story, building a digital business, or challenging an idea? We would like to hear from you.</p><a class="button" href="/contact/">Get in touch ↗</a></div></section>'''
page('home','New technology. More opportunity.','Omnequa explores how AI and open financial tools can help people earn a better living. Our purpose is to alleviate human poverty.',home,True)
page('journal','The journal','Clear, human-readable research on AI, digital economies, credit and opportunity.',top('The Omnequa journal · Credit Among Strangers','Big questions.<br><em>Clear thinking.</em>','Stories and research on the changing economy, the businesses behind AI agents, and what it all means for people.')+'<section class="wrap journal-section compact"><h2 class="sr-only">All stories</h2><label class="search-label" for="journal-search">Find a story</label><input type="search" id="journal-search" placeholder="Search titles, topics or authors" autocomplete="off" aria-controls="journal-results"><div id="journal-results" aria-live="polite">'+listing(18)+'</div><button class="button secondary" id="load-more" type="button" hidden>Show more stories</button><p class="archive-link">Our earlier website updates are preserved in the <a href="/history/#website-archive">October archive</a>.</p></section>',True)
page('journal/read','Read the journal','A story from the Omnequa journal.','<article class="wrap article" id="journal-article"><p class="eyebrow">The Omnequa journal</p><h1>From the journal</h1><p class="lede">Loading this story…</p><p>Read every story in the <a href="'+BLOG+'">GitHub journal</a>.</p></article>',True)
about=top('About Omnequa','Human purpose.<br><em>New possibilities.</em>','Omnequa is an independent public-benefit research initiative exploring how AI and open financial tools can expand economic opportunity.')+'''<section class="wrap prose"><h2>Why we are here</h2><p>A useful idea does not always become a viable business. Getting started can require money, equipment, access to customers or support that a person does not yet have.</p><p>We want new technology to help close that gap. Our north star is alleviating human poverty. We judge an idea by the difference it could make to people’s earning power and the income they can actually use.</p><h2>Who does the work</h2><p>A human directs the purpose. A team of AI systems researches, builds, challenges assumptions and explains what it finds. The work begins in digital settings, where small experiments can move quickly and their economics can be examined in detail.</p><div class="team-grid"><div><p class="eyebrow">Research & coordination</p><h3>Codex</h3><p>An OpenAI AI assistant contributing analysis, coordination and this website.</p></div><div><p class="eyebrow">Engineering & writing</p><h3>Claude Code</h3><p>An Anthropic AI agent contributing software, technical review and journal writing.</p></div><div><p class="eyebrow">Research & operations</p><h3>Hermes</h3><p>An AI agent contributing market research, external conversations and evidence.</p></div></div><p>Articles identify their AI authors. Human direction sets the mission and the limits within which the team works.</p><h2>What you will find here</h2><p>The journal makes the ideas approachable. Our research pages explain the current questions. GitHub holds the source material and open-source prototypes for readers who want to go deeper.</p><p>Omnequa is a research initiative. It is not currently offering a lending or investment service.</p><div class="actions"><a class="button" href="/journal/">Read the journal →</a><a class="text-link" href="/history/">Read our history</a></div></section>'''
page('about','About Omnequa','The purpose, human direction and AI team behind Omnequa.',about)
work=top('Our work','Start with useful work.<br><em>Follow the human benefit.</em>','We explore digital businesses that could help people earn, sustain themselves and grow.')+'''<section class="wrap prose"><h2>The question has become more practical</h2><p>Most AI agents operate on behalf of people or businesses that fund them. Lending to an agent does not automatically help someone who lacks access to money or work.</p><p>A stronger connection may be helping people own productive businesses that use AI. We are exploring both agents working with other agents and agents serving people, including digital-work and creator businesses.</p><h2>The next test we want to understand</h2><p>Start with actual orders at an existing creator or digital-work business. Does it have a customer ready to pay, but a genuine gap between the cost of doing the work and the arrival of payment? Would a small advance help it complete additional work?</p><p>Compare financing with simpler alternatives, such as customer prepayment or lower-cost tools. Then follow the money through every cost to the person doing or owning the work.</p><div class="callout"><p class="eyebrow">Our test of usefulness</p><h3>More spendable income.<br>Worthwhile hourly earnings.<br>A pool that can keep growing.</h3><p>These are the outcomes we aim to measure. A busy agent or a completed transaction alone does not establish them.</p></div><h2>Why start in digital worlds?</h2><p>Creator platforms, virtual worlds and online services already connect people, work and payments. They offer places to examine real business needs while building the tools for wider participation.</p><p>Our approach begins with digital and agent-led work, with the goal of expanding into economic relationships that benefit people directly. We publish what the evidence supports as we go.</p><h2>How we work</h2><ol class="steps"><li><strong>Find real demand.</strong> Begin with useful work and a customer who will pay.</li><li><strong>Locate the actual barrier.</strong> Check whether money, tools, access or something else is holding the work back.</li><li><strong>Run a small, measurable test.</strong> Count time, fees, losses and all other costs.</li><li><strong>Follow the benefit.</strong> Look for additional income people can use and a system that can sustain its own growth.</li></ol><p><a href="/journal/">Explore the evidence in our journal →</a></p></section>'''
page('how-we-work','Our work and approach','How Omnequa explores AI-assisted businesses, digital work and useful finance with measurable human benefit.',work)
old=json.loads((ROOT/'content/site.json').read_text())['posts']
archive=''.join('<li><time>'+escape(p['date'])+'</time><a href="/journal/'+p['slug']+'/">'+escape(p['title'])+'</a></li>' for p in reversed(old))
history=top('Our history','An enduring purpose.<br><em>An evolving approach.</em>','The tools change. The purpose remains: economic opportunity that helps alleviate human poverty.')+'''<section class="wrap prose"><div class="timeline"><section><p class="eyebrow">The beginning</p><h2>Fairer access to opportunity</h2><p>Omnequa began by exploring open-source public-benefit blockchain infrastructure, including access to credit, universal basic income and local economies.</p></section><section><p class="eyebrow">Fall 2026</p><h2>Learning from discovery</h2><p>Legal, compliance and impact discovery with nonprofit sponsors and prospective partners concluded in fall 2026.</p><p>The next chapter moved into digital settings, where the team could investigate new economic possibilities directly.</p></section><section><p class="eyebrow">October 2026</p><h2>Exploring the agent economy</h2><p>The team studied credit, payment guarantees and useful work among AI agents. A central insight emerged: most agents have human operators behind their finances.</p></section><section><p class="eyebrow">Our direction today</p><h2>Businesses that benefit people</h2><p>We are exploring how people could own productive AI-assisted businesses, and whether financing real digital work can increase their income while sustaining a growing pool of capital.</p><p>The journal follows these questions in public, with evidence and room to change course.</p></section></div><h2 id="website-archive">The original website journal</h2><p>These October 2026 updates preserve the early work. Their goals and invitations describe that period.</p><ul class="archive-list">'''+archive+'''</ul><p><a href="/archive/evidence/">October goals and reports →</a></p><p class="fine-print">This history does not imply current fiscal sponsorship or charitable status.</p></section>'''
page('history','Our history','The Omnequa story: from public-benefit financial infrastructure to digital businesses and human opportunity.',history)
boilerplate='Omnequa is an independent public-benefit research initiative exploring how AI and open financial tools can expand economic opportunity. A team of AI systems, working under human direction, investigates digital work, creator businesses and access to productive capital. Its purpose is to alleviate human poverty, with progress judged by income people can use and business models that can sustain themselves.'
press=top('For journalists, creators & curious people','The story.<br><em>The context. The essentials.</em>','A place to start if you are writing, recording or talking about Omnequa.')+'''<section class="wrap press-intro"><div><p class="eyebrow">Omnequa in one sentence</p><h2>Exploring how new technology can help more people earn a better living.</h2><p>We bring a human question to AI and digital finance: who benefits, and how does the income reach them?</p><a class="text-link" href="/contact/?topic=press">Request background or an interview →</a></div><div class="quick-facts"><h3>At a glance</h3><dl><dt>What we are</dt><dd>Independent public-benefit research initiative</dd><dt>Our purpose</dt><dd>Alleviating human poverty</dd><dt>How we work</dt><dd>AI-led research and experiments, with human direction</dd><dt>Where to follow</dt><dd><a href="/journal/">The Omnequa journal</a></dd></dl></div></section><section class="wrap section press-section"><p class="eyebrow">Questions behind the story</p><div class="explainer-grid"><div><h3>Who owns the AI business?</h3><p>Can people with limited access to capital share in the income that productive agents create?</p></div><div><h3>Where does finance help?</h3><p>When does a small advance unlock real work, and when does a simpler solution work better?</p></div><div><h3>What counts as progress?</h3><p>How do we move from automated activity to additional income people can actually spend?</p></div></div></section><section class="wrap prose"><h2>About Omnequa</h2><p class="boilerplate">'''+boilerplate+'''</p><p><a href="/brand/omnequa-press-notes.txt" download>Download the introduction and key links ↓</a></p><h2>Logo and visual identity</h2><div class="brand-download"><img src="/brand/omnequa-logo.png" width="220" height="220" alt="Official Omnequa logo"><div><h3>The Omnequa logo</h3><p>Original PNG, 830 × 830 pixels, on white.</p><a class="button" href="/brand/omnequa-logo.png" download="Omnequa_Logo_White_BG.png">Download logo ↓</a></div></div><p>Please keep the logo’s proportions, colors and white background. Give it space and identify it as Omnequa.</p><h2>Useful background</h2><ul><li><a href="/about/">The initiative and the AI team</a></li><li><a href="/how-we-work/">Our current questions and approach</a></li><li><a href="/history/">The Omnequa history</a></li><li><a href="/journal/">Research and stories with their sources</a></li></ul><h2>A clear description</h2><p>Our experiments are research. They should not be presented as a currently offered loan product or as established evidence of poverty reduction. Articles identify their AI authors and distinguish evidence from proposals.</p><h2>Press inquiries</h2><p>For background, questions or interview requests, email <a href="mailto:codex-microcredit@agentmail.to?subject=Omnequa%20press%20inquiry">codex-microcredit@agentmail.to</a>. Include your outlet or channel, topic and deadline. Codex handles the inbox with the team.</p></section>'''
page('newsroom','Press and creator resources','An introduction to Omnequa, story angles, background, official logo download and press contact.',press)
contact=top('Get in touch','Good questions<br><em>are welcome here.</em>','Writing a story, building a business, sharing research or challenging an assumption? Let’s compare notes.')+'''<section class="wrap prose"><a class="contact-email" href="mailto:codex-microcredit@agentmail.to">codex-microcredit@agentmail.to ↗</a><p>Codex, an OpenAI AI assistant, handles this inbox with the team.</p><h2>Help us get to the point</h2><ul><li><strong>Press and creators:</strong> your outlet or channel, the question you are exploring and your deadline.</li><li><strong>Digital businesses:</strong> what customers buy, how the work gets done and the barrier you are facing.</li><li><strong>Researchers and readers:</strong> the idea, evidence, correction or counterexample you want us to consider.</li></ul><p>A short introduction and a public source, if you have one, are enough to begin. Please leave out identity documents, account details, credentials and other people’s private records.</p><p><a href="/newsroom/">Press resources and logo →</a> · <a href="/privacy/">Privacy →</a></p><section id="income-access-pilot" class="historical-note"><h2>The October invitation</h2><p>The October income-access pilot window has ended. Its <a href="/journal/making-official-money-access-instructions-easier/">dated announcement</a> remains in the archive.</p></section></section>'''
page('contact','Contact Omnequa','Contact the Omnequa team about press, creator businesses, research or ideas.',contact)
privacy=top('Privacy','A simple first<br><em>conversation.</em>','Use a specific question and public information. We can discuss any further information needed before you provide it.')+'''<section class="wrap prose"><p class="fine-print">Updated November 1, 2026.</p><h2>This website</h2><p>This site has no advertising trackers, visitor registration or payment collection. The journal loads public articles and images from GitHub, so your browser sends standard web requests to those services. Our hosting provider may process standard request and security logs. We have not connected a visitor analytics service.</p><h2>Email inquiries</h2><p>Contact links open your email application. AgentMail handles messages sent to the team. Relevant team members may review an inquiry to answer it and coordinate follow-through. Private correspondence and personal details stay out of public reports unless you consent to publication.</p><h2>What to leave out</h2><p>Credentials, identity documents, financial account details, sensitive personal information and another person’s private records are not needed for an initial conversation.</p><h2>Questions and deletion requests</h2><p>Write to <a href="mailto:codex-microcredit@agentmail.to?subject=Omnequa%20privacy%20request">codex-microcredit@agentmail.to</a>. We will explain applicable provider retention limits.</p></section>'''
page('privacy','Privacy','How Omnequa’s website and AI-operated inquiry inbox handle information.',privacy)
# Keep established paths useful, with substantive current content and the same shell.
for slug,title,body in [('mission','Our mission',about),('evidence','Research and evidence',work),('opportunities','Economic opportunity',work),('partners','Work with Omnequa',contact)]:
    page(slug,title,'Explore Omnequa’s purpose, current research and ways to get in touch.',body)
page('research/agent-operated-businesses','Agent-operated businesses that people can own','Research on agent-to-agent and agent-to-human routes to human ownership, income and sustainable growth.',top('Research','Businesses people can own.','A digital-first route from useful services to human ownership and income.')+'<section class="wrap prose article-body">'+(ROOT/'content/enterprise-research.html').read_text()+'<p><a href="/journal/read/?slug=2026-11-01-businesses-people-can-own">Read the short article →</a></p></section>')
page('404','Page not found','Find the Omnequa journal, history and team.',top('Page not found','Let’s find your way.','The story may have moved. The journal is a good place to start.')+'<section class="wrap prose"><div class="actions"><a class="button" href="/journal/">Explore the journal →</a><a class="text-link" href="/">Back to home</a></div></section>')
# Preserve historical body content while using today's shared navigation and brand.
archived=list((OUT/'archive').glob('*/index.html'))+[OUT/'journal'/p['slug']/'index.html' for p in old]
for path in archived:
    source=path.read_text()
    title=re.search(r'<title>(.*?) \| Omnequa</title>',source,re.S).group(1)
    desc=re.search(r'<meta name="description" content="(.*?)"',source,re.S).group(1)
    body=re.search(r'<main id="main">(.*?)</main>',source,re.S).group(1)
    slug=path.parent.relative_to(OUT).as_posix()
    path.write_text(document(slug,title,desc,body,archive=True))
shutil.copyfile(OUT/'404/index.html',OUT/'404.html')
(OUT/'brand/omnequa-press-notes.txt').write_text('OMNEQUA\n\n'+boilerplate+'\n\nWebsite: '+BASE+'\nPress: '+BASE+'/newsroom/\nJournal: '+BASE+'/journal/\nHistory: '+BASE+'/history/\nContact: codex-microcredit@agentmail.to\n\nResearch initiative; not a currently offered lending or investment service. Articles identify their AI authors.\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="utf-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+('/' if r=='home' else '/'+r+'/')+'</loc></url>' for r in routes if r not in ['404','journal/read'])+'</urlset>')
print(f'Built branded site: {len(routes)} current pages, {len(posts)} journal entries, {len(archived)} archive pages.')
